WITH latest AS (SELECT upid,heap_name,MAX(ts) AS ts FROM heap_profile_allocation GROUP BY upid,heap_name)
SELECT a.upid,p.pid,a.heap_name,a.ts,a.callsite_id,SUM(a.size) AS sampled_unreleased_malloc_bytes,SUM(a.count) AS sampled_unreleased_malloc_count,SUM(CASE WHEN a.size>0 THEN a.size ELSE 0 END) AS sampled_total_malloc_bytes,f.name AS leaf_name,f.rel_pc,m.name AS mapping_name,m.build_id FROM heap_profile_allocation a JOIN latest l USING(upid,heap_name,ts) LEFT JOIN process p USING(upid) JOIN stack_profile_callsite c ON a.callsite_id=c.id JOIN stack_profile_frame f ON c.frame_id=f.id JOIN stack_profile_mapping m ON f.mapping=m.id GROUP BY a.upid,p.pid,a.heap_name,a.ts,a.callsite_id,f.name,f.rel_pc,m.name,m.build_id ORDER BY sampled_unreleased_malloc_bytes DESC;
